def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Mark zero cells reachable from the border using four-way movement.
    exterior = set()
    queue = deque()
    for r in range(h):
        for c in range(w):
            if (r == 0 or r == h - 1 or c == 0 or c == w - 1) and grid[r][c] == 0:
                exterior.add((r, c))
                queue.append((r, c))
    for r, c in queue:
