    while queue:
        r, c = queue.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and (nr, nc) not in exterior:
                exterior.add((nr, nc))
                queue.append((nr, nc))

    inside = {(r, c) for r in range(h) for c in range(w)
              if grid[r][c] == 0 and (r, c) not in exterior}

    # Color enclosed cells that touch a 1 diagonally or orthogonally.
    for r, c in inside:
        if any(0 <= r + dr < h and 0 <= c + dc < w and grid[r + dr][c + dc] == 1
               for dr in (-1, 0, 1) for dc in (-1, 0, 1) if dr or dc):
            out[r][c] = 3

    # Find each 4-connected 1 component. Only components adjacent to an
    # enclosed zero area receive the surrounding color.
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or (r, c) in seen:
                continue
            queue = [(r, c)]
            seen.add((r, c))
            component = {(r, c)}
            for x, y in queue:
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = x + dr, y + dc
                    if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 1
                            and (nr, nc) not in seen):
                        seen.add((nr, nc))
                        component.add((nr, nc))
                        queue.append((nr, nc))
            touches_inside = any((x + dr, y + dc) in inside
                                 for x, y in component
                                 for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)))
            if not touches_inside:
                continue

            # Paint the one-cell 8-neighbor outer halo.
            for x, y in component:
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        nr, nc = x + dr, y + dc
                        if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0
                                and (nr, nc) not in inside):
                            out[nr][nc] = 2

            # When the component traces every edge of its bounding box
            # (allowing diagonal corner contacts), complete the outer frame.
            r0 = min(x for x, _ in component)
            r1 = max(x for x, _ in component)
            c0 = min(y for _, y in component)
            c1 = max(y for _, y in component)
            boundary = {(rr, cc) for rr in range(r0, r1 + 1)
                        for cc in range(c0, c1 + 1)
                        if rr in (r0, r1) or cc in (c0, c1)}
            traces_box = all(any((rr + dr, cc + dc) in component
                                 for dr in (-1, 0, 1) for dc in (-1, 0, 1))
                             for rr, cc in boundary)
            if traces_box:
                frame = ([(r0 - 1, cc) for cc in range(c0 - 1, c1 + 2)]
                         + [(r1 + 1, cc) for cc in range(c0 - 1, c1 + 2)]
                         + [(rr, c0 - 1) for rr in range(r0, r1 + 1)]
                         + [(rr, c1 + 1) for rr in range(r0, r1 + 1)])
                for rr, cc in frame:
                    if (0 <= rr < h and 0 <= cc < w and grid[rr][cc] == 0
                            and (rr, cc) not in inside):
                        out[rr][cc] = 2

    return out
